SET NAMES utf8mb4;

USE `vita_game`;

DROP TEMPORARY TABLE IF EXISTS `tmp_difficulty_ranges_2000`;

DROP TEMPORARY TABLE IF EXISTS `tmp_difficulty_levels_2000`;

CREATE TEMPORARY TABLE `tmp_difficulty_ranges_2000` (
  `range_key` INT UNSIGNED NOT NULL,
  `start_level` INT UNSIGNED NOT NULL, `end_level` INT UNSIGNED NOT NULL,
  `difficulty` TINYINT UNSIGNED NOT NULL, `grid_w` SMALLINT UNSIGNED NOT NULL, `grid_h` SMALLINT UNSIGNED NOT NULL,
  `max_layers` SMALLINT UNSIGNED NOT NULL, `min_tiles` SMALLINT UNSIGNED NOT NULL, `max_tiles` SMALLINT UNSIGNED NOT NULL,
  `chaos` DECIMAL(5,4) NOT NULL, `min_available_pairs` SMALLINT UNSIGNED NOT NULL,
  `hidden_ratio` DECIMAL(5,4) NOT NULL, `special_pair_count` SMALLINT UNSIGNED NOT NULL,
  `curve_type` VARCHAR(16) NOT NULL, `curve_amplitude` DECIMAL(6,4) NOT NULL, `curve_cycles` DECIMAL(6,2) NOT NULL,
  `updated_at` DATETIME NOT NULL, PRIMARY KEY (`range_key`)
) ENGINE=InnoDB;

CREATE TEMPORARY TABLE `tmp_difficulty_levels_2000` (
  `level` INT UNSIGNED NOT NULL, `range_key` INT UNSIGNED NOT NULL,
  `difficulty` TINYINT UNSIGNED NOT NULL, `difficulty_label` VARCHAR(16) NOT NULL,
  `curve_factor` DECIMAL(7,4) NOT NULL, `manual_override` TINYINT(1) NOT NULL,
  `grid_w` SMALLINT UNSIGNED NOT NULL, `grid_h` SMALLINT UNSIGNED NOT NULL, `max_layers` SMALLINT UNSIGNED NOT NULL,
  `min_tiles` SMALLINT UNSIGNED NOT NULL, `max_tiles` SMALLINT UNSIGNED NOT NULL, `chaos` DECIMAL(5,4) NOT NULL,
  `min_available_pairs` SMALLINT UNSIGNED NOT NULL, `hidden_ratio` DECIMAL(5,4) NOT NULL,
  `special_pair_count` SMALLINT UNSIGNED NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`level`)
) ENGINE=InnoDB;












START TRANSACTION;
DELETE FROM `game_difficulty_levels` WHERE `mode`='normal';
DELETE FROM `game_difficulty_ranges` WHERE `mode`='normal';
SELECT 'normal',`start_level`,`end_level`,`difficulty`,`grid_w`,`grid_h`,`max_layers`,`min_tiles`,`max_tiles`,`chaos`,`min_available_pairs`,`hidden_ratio`,`special_pair_count`,`curve_type`,`curve_amplitude`,`curve_cycles`,`updated_at` FROM `tmp_difficulty_ranges_2000` ORDER BY `range_key`;
SELECT 'normal',l.`level`,r.`id`,l.`difficulty`,l.`difficulty_label`,l.`curve_factor`,l.`manual_override`,l.`grid_w`,l.`grid_h`,l.`max_layers`,l.`min_tiles`,l.`max_tiles`,l.`chaos`,l.`min_available_pairs`,l.`hidden_ratio`,l.`special_pair_count`,l.`updated_at`
FROM `tmp_difficulty_levels_2000` l
JOIN `tmp_difficulty_ranges_2000` t ON t.`range_key`=l.`range_key`
JOIN `game_difficulty_ranges` r ON r.`mode`='normal' AND r.`start_level`=t.`start_level` AND r.`end_level`=t.`end_level`;
COMMIT;

SELECT `mode`,COUNT(*) AS `level_count`,MIN(`level`) AS `min_level`,MAX(`level`) AS `max_level` FROM `game_difficulty_levels` GROUP BY `mode` ORDER BY `mode`;
SELECT COUNT(*) AS `normal_range_count` FROM `game_difficulty_ranges` WHERE `mode`='normal';
DROP TEMPORARY TABLE IF EXISTS `tmp_difficulty_levels_2000`;
DROP TEMPORARY TABLE IF EXISTS `tmp_difficulty_ranges_2000`;
